1. import * as aws from './aws';
2. import * as core from '@actions/core';
3. import {Exec} from '@docker/actions-toolkit/lib/exec';
4. 
5. export async function login(registry: string, username: string, password: string, ecr: string): Promise<void> {
6.   if (/true/i.test(ecr) || (ecr == 'auto' && aws.isECR(registry))) {
7.     await loginECR(registry, username, password);
8.   } else {
9.     await loginStandard(registry, username, password);
10.   }
11. }
12. 
13. export async function logout(registry: string): Promise<void> {
14.   await Exec.getExecOutput('docker', ['logout', registry], {
15.     ignoreReturnCode: true
16.   }).then(res => {
17.     if (res.stderr.length > 0 && res.exitCode != 0) {
18.       core.warning(res.stderr.trim());
19.     }
20.   });
21. }
22. 
23. export async function loginStandard(registry: string, username: string, password: string): Promise<void> {
24.   if (!username && !password) {
25.     throw new Error('Username and password required');
26.   }
27.   if (!username) {
28.     throw new Error('Username required');
29.   }
30.   if (!password) {
31.     throw new Error('Password required');
32.   }
33. 
34.   const loginArgs: Array<string> = ['login', '--password-stdin'];
35.   loginArgs.push('--username', username);
36.   loginArgs.push(registry);
37. 
38.   if (registry) {
39.     core.info(`Logging into ${registry}...`);
40.   } else {
41.     core.info(`Logging into Docker Hub...`);
42.   }
43.   await Exec.getExecOutput('docker', loginArgs, {
44.     ignoreReturnCode: true,
45.     silent: true,
46.     input: Buffer.from(password)
47.   }).then(res => {
48.     if (res.stderr.length > 0 && res.exitCode != 0) {
49.       throw new Error(res.stderr.trim());
50.     }
51.     core.info(`Login Succeeded!`);
52.   });
53. }
54. 
55. export async function loginECR(registry: string, username: string, password: string): Promise<void> {
56.   core.info(`Retrieving registries data through AWS SDK...`);
57.   const regDatas = await aws.getRegistriesData(registry, username, password);
58.   for (const regData of regDatas) {
59.     core.info(`Logging into ${regData.registry}...`);
60.     await Exec.getExecOutput('docker', ['login', '--password-stdin', '--username', regData.username, regData.registry], {
61.       ignoreReturnCode: true,
62.       silent: true,
63.       input: Buffer.from(regData.password)
64.     }).then(res => {
65.       if (res.stderr.length > 0 && res.exitCode != 0) {
66.         throw new Error(res.stderr.trim());
67.       }
68.       core.info('Login Succeeded!');
69.     });
70.   }
71. }
